import { cn } from "@utils/cn"
import type { ComponentPropsWithoutRef, ReactNode } from "react"
import { forwardRef } from "react"

import { recipe, type TextFieldVariantProps } from "./recipe"

const getHelperText = (id: string) => `${id}-helper-text`

type TextFieldProps = Omit<
  ComponentPropsWithoutRef<"input">,
  "size" | "width"
> & {
  leadingAddon?: ReactNode
  trailingAddon?: ReactNode
  label?: string
  helperText?: string
  required?: boolean
  id: string
} & TextFieldVariantProps

export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(
  (props, ref) => {
    const {
      className,
      leadingAddon,
      trailingAddon,
      label,
      helperText,
      id,
      required = false,
      status,
      ...rest
    } = props

    const styles = recipe({ status })
    return (
      <div className={styles.root()}>
        {label && (
          <div className={styles.heading()}>
            <label htmlFor={id}>
              {label}
              {required && <span className="ml-0.5 text-sm text-error">*</span>}
            </label>
          </div>
        )}

        <div className={styles.container()}>
          {leadingAddon && <div>{leadingAddon}</div>}

          <input
            ref={ref}
            className={cn(styles.input(), className)}
            required={required}
            id={id}
            aria-describedby={getHelperText(id)}
            aria-invalid={status === "negative" ? true : false}
            {...rest}
          />

          {trailingAddon && (
            <div className={styles.trailingButton()}>{trailingAddon}</div>
          )}
        </div>

        {helperText && (
          <div
            className={styles.helper()}
            id={getHelperText(id)}
            aria-live="polite"
          >
            {helperText}
          </div>
        )}
      </div>
    )
  },
)

TextField.displayName = "TextField"

import { tv, type VariantProps } from "tailwind-variants"

export const recipe = tv({
  slots: {
    root: "flex w-full flex-col gap-1.5",
    heading: "text-sm/snug font-semibold tracking-wide",
    container: [
      "flex min-h-12 w-full items-center gap-1.5 p-3",
      "rounded-md border border-base-200 shadow-sm",
      "transition-colors duration-150 ease-in",
      "has-disabled:cursor-not-allowed",
      "focus-within:border-primary",
    ],
    input: `
      flex-1 border-none outline-none
      disabled:cursor-not-allowed
    `,
    trailingButton: "flex max-h-2 items-center whitespace-nowrap",
    helper: `
      self-stretch text-[0.625rem] leading-tight font-semibold tracking-wide
      text-base-content/60
    `,
  },
  variants: {
    status: {
      normal: {},
      negative: {
        container: `
          border-error
          focus-within:border-error
        `,
        helper: "text-error",
      },
    },
  },
  defaultVariants: {
    status: "normal",
  },
})

export type TextFieldVariantProps = VariantProps<typeof recipe>
